    const escapeChar: string = this.current;
    switch (escapeChar) {
      case 'n': result = '\n'; break;
      case 't': result = '\t'; break;
      case 'r': result = '\r'; break;
      case '\\': result = '\\'; break;
      case "'": result = "'"; break;
      case '0': result = '\0'; break;
