 *
 * 예: /[0-9]+/g, /test/i, /^hello$/
 */
private readRegex(): string {
  this.readChar(); // skip opening /

  let pattern = '';
  while (this.current !== '/' && this.current !== '\0') {
    if (this.current === '\\') {
      pattern += this.current;
      this.readChar();
